$root='api/LuxuryApp.Application/Modules/MantenimientoLuxuryApp/SmokeDetectorInventory'; $dto="$root/DTOs"; $src=Get-Content "$dto/InventarioDetectorHumoAddOrEditDTO.cs" -Raw; Set-Content "$dto/CreateSmokeDetectorDTO.cs" ($src.Replace('InventarioDetectorHumoAddOrEditDTO','CreateSmokeDetectorDTO')) -NoNewline; Set-Content "$dto/UpdateSmokeDetectorDTO.cs" ($src.Replace('InventarioDetectorHumoAddOrEditDTO','UpdateSmokeDetectorDTO')) -NoNewline; $read=Get-Content "$dto/InventarioDetectorHumoDTO.cs" -Raw; Set-Content "$dto/SmokeDetectorDTO.cs" ($read.Replace('InventarioDetectorHumoDTO','SmokeDetectorDTO')) -NoNewline; Remove-Item "$dto/InventarioDetectorHumoAddOrEditDTO.cs","$dto/InventarioDetectorHumoDTO.cs"; $map=@{'InventarioDetectorHumoAddOrEditDTO'='CreateSmokeDetectorDTO';'InventarioDetectorHumoDTO'='SmokeDetectorDTO'}; Get-ChildItem $root -Recurse -File -Filter *.cs | ForEach-Object {$c=Get-Content $_.FullName -Raw; foreach($k in $map.Keys){$c=$c.Replace($k,$map[$k])}; $c=$c.Replace('ApiResponseDTO<CreateSmokeDetectorDTO>> GetByIdAsync','ApiResponseDTO<UpdateSmokeDetectorDTO>> GetByIdAsync').Replace('ApiResponseDTO<CreateSmokeDetectorDTO>>.ErrorResult','ApiResponseDTO<UpdateSmokeDetectorDTO>>.ErrorResult').Replace('new CreateSmokeDetectorDTO','new UpdateSmokeDetectorDTO').Replace('UpdateAsync(Guid id, CreateSmokeDetectorDTO','UpdateAsync(Guid id, UpdateSmokeDetectorDTO').Replace('MapPut("{id:guid}", async (Guid id, CreateSmokeDetectorDTO','MapPut("{id:guid}", async (Guid id, UpdateSmokeDetectorDTO'); Set-Content $_.FullName $c -NoNewline}
